"""Compare two fresh Marked stage logs with two independently maintained parsers."""
import hashlib
import json
from pathlib import Path
import subprocess
import sys

import markdown_it


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run(pure_log, develop_log, commonmark):
    pure = json.loads(pure_log.read_bytes())
    develop = json.loads(develop_log.read_bytes())
    assert [(r["source"], r["expected"]) for r in pure] == [
        (r["source"], r["expected"]) for r in develop]
    javascript = """
    const fs = require('node:fs');
    const path = require('node:path');
    const {Parser, HtmlRenderer} = require(process.argv[1]);
    const parser = new Parser(), renderer = new HtmlRenderer();
    const inputs = JSON.parse(fs.readFileSync(0, 'utf8'));
    const html = inputs.map(s => renderer.render(parser.parse(s)).match(/^<p>([\\s\\S]*)<\\/p>\\n$/)[1]);
    console.log(JSON.stringify(html));
    """
    outputs = subprocess.run(["node", "-e", javascript, str(commonmark.resolve())],
                             input=json.dumps([r["source"] for r in pure]), text=True,
                             capture_output=True, check=True)
    py_parser = markdown_it.MarkdownIt("commonmark")
    return {"markdown_it_py_version": markdown_it.__version__,
            "commonmark_js_version": json.loads((commonmark / "package.json").read_bytes())["version"],
            "commonmark_js_sha256": digest(commonmark / "dist/commonmark.js"),
            "stage_logs_sha256": [digest(pure_log), digest(develop_log)],
            "rows": [{"source": c["source"], "frozen": c["expected"], "pure": c["actual"],
                      "develop": d["actual"], "commonmark_js": js,
                      "markdown_it_py": py_parser.renderInline(c["source"])}
                     for c, d, js in zip(pure, develop, json.loads(outputs.stdout), strict=True)]}


if __name__ == "__main__":
    print(json.dumps(run(*(Path(v) for v in sys.argv[1:])), ensure_ascii=False, indent=2))
